 final LauncherActivity a;final NativeMusicEngine engine;final EditText query;final TextView heading,status,title,artist,play,timing;final SeekBar seek;final ListView list;final ArrayAdapter<String> adapter;final List<MusicTrack> results=new ArrayList<>();final ExecutorService network=Executors.newSingleThreadExecutor();BitChordCatalogue search;Future<?> job;boolean closed,visible,queueTab,dragging;int request;
