 void search(){String q=query.getText().toString().trim();if(q.isEmpty())return;a.hideKeyboard();request++;int ticket=request;if(job!=null)job.cancel(true);if(search!=null)search.close();search=new BitChordCatalogue();BitChordCatalogue client=search;queueTab=false;results.clear();rows();status.setText("Mencari…");job=network.submit(()->{try{List<MusicTrack> found=client.search(q);a.main.post(()->{if(!closed&&ticket==request){results.clear();results.addAll(found);rows();status.setText(found.isEmpty()?"Tiada hasil katalog":"Tekan lagu untuk main · "+found.size()+" hasil");}});}catch(Exception e){a.main.post(()->{if(!closed&&ticket==request)status.setText("Carian gagal: "+e.getMessage());});}});}
